package hugolib

import (
	"testing"

	qt "github.com/frankban/quicktest"
)

func TestHashInPermalinkIssue12343(t *testing.T) {
	t.Parallel()

	files := `
-- hugo.toml --
baseURL = "http://example.com/"
disableKinds = ["taxonomy", "term", "RSS", "sitemap"]
[permalinks]
posts = "/posts/:year/:month/:slug/"
-- content/posts/hash-in-title.md --
---
title: 'Newsletter #4'
date: 2024-04-04T12:27:52-07:00
---
Foo
-- layouts/_default/single.html --
Rel: {{ .RelPermalink }}
Perma: {{ .Permalink }}
`

	b := NewIntegrationTestBuilder(
		IntegrationTestConfig{
			T:           t,
			TxtarString: files,
		},
	).Build()

	b.AssertFileContent("public/posts/2024/04/newsletter-#4/index.html",
		"Rel: /posts/2024/04/newsletter-%234/",
		"Perma: http://example.com/posts/2024/04/newsletter-%234/",
	)
}

