package paths

import (
	"fmt"
	"testing"

	qt "github.com/frankban/quicktest"
)

func TestPathEscapeHash(t *testing.T) {
	c := qt.New(t)

	for _, test := range []struct {
		in   string
		want string
	}{
		{"/posts/2024/04/newsletter-#4/index.html", "/posts/2024/04/newsletter-%234/index.html"},
		{"/posts/a?b/index.html", "/posts/a%3Fb/index.html"},
		{"/posts/hello world/index.html", "/posts/hello%20world/index.html"},
		{"/posts/h%C3%A6llo/index.html", "/posts/h%C3%A6llo/index.html"},
		{"/posts/hello/index.html", "/posts/hello/index.html"},
		{"/a/b#frag", "/a/b%23frag"},
		{"/a/b?q=1", "/a/b%3Fq=1"},
		{"/a/b%23already", "/a/b%23already"},
	} {
		got := PathEscape(test.in)
		c.Assert(got, qt.Equals, test.want, qt.Commentf("input %s", test.in))
		fmt.Println(test.in, "=>", got)
	}
}

